import React, { useState } from 'react';
import { createTestDrive } from '../services/testDriveService';
import { useAuth } from '../context/AuthContext';

const TestDriveForm = ({ carId }) => {
  const { user } = useAuth();
  const [date, setDate] = useState('');
  const [phone, setPhone] = useState('');
  const [message, setMessage] = useState('');
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');

  const validatePhone = (value) => {
    const cleaned = value.replace(/\D/g, '');
    if (cleaned.length !== 11) return false;
    if (cleaned[0] !== '7' && cleaned[0] !== '8') return false;
    return true;
  };

  const formatPhone = (value) => {
    const digits = value.replace(/\D/g, '');
    if (digits.length === 0) return '';
    if (digits[0] === '8') return `8${digits.slice(1, 11)}`;
    return `+7${digits.slice(1, 11)}`;
  };

  const handlePhoneChange = (e) => {
    setPhone(formatPhone(e.target.value));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validatePhone(phone)) {
      setError('Неверный формат телефона');
      return;
    }
    try {
      await createTestDrive({ car_id: carId, date, phone, message });
      setSuccess(true);
      setError('');
    } catch (err) {
      setError(err.response?.data?.detail || 'Ошибка при записи');
    }
  };

  if (success) {
    return (
      <div style={{ textAlign: 'center', padding: '2rem', color: 'var(--text)' }}>
        <h4 style={{ color: '#4CAF50', marginBottom: '0.5rem', fontSize: '1.4rem' }}>Успешно!</h4>
        <p style={{ opacity: 0.9 }}>Вы успешно записались на тест-драйв. Менеджер свяжется с вами в ближайшее время.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1.2rem' }}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.4rem' }}>
        <label style={{ fontSize: '0.9rem', fontWeight: '500', color: 'var(--text)', opacity: 0.8 }}>
          Выберите дату и время тест-драйва:
        </label>
        <input 
          type="datetime-local" 
          value={date} 
          onChange={(e) => setDate(e.target.value)} 
          required
          style={{ 
            padding: '0.8rem 1rem', 
            borderRadius: '12px', 
            border: '2px solid rgba(128, 128, 128, 0.25)', 
            background: 'var(--bg)', 
            color: 'var(--text)', 
            fontFamily: 'inherit',
            outline: 'none',
            width: '100%',
            boxSizing: 'border-box',
            colorScheme: 'dark light', /* Адаптирует интерфейс календаря под тему */
            cursor: 'pointer'
          }} 
        />
      </div>

      <input
        type="tel"
        placeholder="Телефон (+79161234567)"
        value={phone}
        onChange={handlePhoneChange}
        required
        pattern="(\+7|8)\d{10}"
        title="Введите номер в формате +79161234567 или 89161234567"
        style={{ 
          padding: '0.8rem 1rem', 
          borderRadius: '12px', 
          border: error ? '2px solid #D32F2F' : '2px solid rgba(128, 128, 128, 0.25)', 
          background: 'var(--bg)', 
          color: 'var(--text)', 
          fontFamily: 'inherit',
          outline: 'none',
          width: '100%',
          boxSizing: 'border-box'
        }}
      />
      
      <textarea 
        placeholder="Сообщение (необязательно)" 
        value={message} 
        onChange={(e) => setMessage(e.target.value)}
        rows="3"
        style={{ 
          padding: '0.8rem 1rem', 
          borderRadius: '12px', 
          border: '2px solid rgba(128, 128, 128, 0.25)', 
          background: 'var(--bg)', 
          color: 'var(--text)', 
          fontFamily: 'inherit', 
          resize: 'vertical',
          outline: 'none',
          width: '100%',
          boxSizing: 'border-box'
        }} 
      />
      
      {error && <p style={{ color: '#D32F2F', fontSize: '0.9rem', margin: 0, fontWeight: '500' }}>{error}</p>}
      
      <button 
        type="submit" 
        style={{
          background: 'linear-gradient(135deg, var(--primary), var(--primary-light))',
          color: 'white',
          border: 'none',
          padding: '0.9rem',
          borderRadius: '12px',
          fontWeight: '600',
          cursor: 'pointer',
          fontFamily: 'inherit',
          transition: 'opacity 0.2s',
          width: '100%'
        }}
      >
        Записаться
      </button>
    </form>
  );
};

export default TestDriveForm;
